// reading-paths.js - curated reading paths (generated from scratchpad design2\paths.json by make-paths.ps1).

var READING_PATHS = [
  {slug:"silk-road",title:"The Silk Road",tagline:"Follow silk, ideas and armies along the routes that bound Eurasia together.",types:["navigator","builder"],intro:"For over fifteen centuries, overland routes across Central Asia carried silk westward and horses, glass and gold eastward, along with religions and technologies. No single empire owned the Silk Road; instead, a relay of states opened, taxed, protected and sometimes disrupted it. This path follows that relay from the Han missions of the second century BCE, through the Parthian middlemen and the cosmopolitan markets of Tang Chang'an, to the Mongol peace and the Timurid splendour of Samarkand.",steps:[
    {name:"Han Dynasty",href:"/empire/han-dynasty",img:"/images/encyclopedia/liu-bang.jpg",meta:"Profile · 206 BCE – 220 CE",why:"Zhang Qian's missions and Emperor Wu's western campaigns opened the routes, and Han garrisons in the Tarim Basin kept them running."},
    {name:"Silk Road",href:"/encyclopedia/silk-road",img:"",meta:"Encyclopedia · Term",why:"An overview of the network itself: its routes, its goods and the ideas, Buddhism among them, that travelled along it."},
    {name:"Parthian Empire",href:"/empire/parthian-empire",img:"/images/encyclopedia/arsaces-i.jpg",meta:"Profile · 247 BCE – 224 CE",why:"Astride key segments of the route, Parthia profited as the intermediary between Rome and Han China, which knew it as Anxi."},
    {name:"Sogdians",href:"/encyclopedia/sogdians",img:"",meta:"Encyclopedia · People",why:"The Central Asian merchant people whose caravans and partnerships carried much of the trade between steppe, oasis and city."},
    {name:"Tang Dynasty",href:"/empire/tang-dynasty",img:"/images/encyclopedia/emperor-gaozu-of-tang.jpg",meta:"Profile · 618 CE – 907 CE",why:"Tang Chang'an, with perhaps a million people, hosted Sogdian, Persian, Arab and Indian merchants in its two great markets."},
    {name:"Battle of Talas",href:"/encyclopedia/battle-of-talas",img:"/images/encyclopedia/battle-of-talas.jpg",meta:"Encyclopedia · Event · 751",why:"In 751 Abbasid forces checked Tang expansion in Central Asia, an encounter traditionally linked with the westward spread of papermaking."},
    {name:"Mongol Empire",href:"/empire/mongol-empire",img:"/images/encyclopedia/karakorum.jpg",meta:"Profile · 1206 CE – 1368 CE",why:"Mongol conquest joined China to Europe, with merchants protected by the Pax Mongolica and envoys speeded by the yam relay system."},
    {name:"Pax Mongolica",href:"/encyclopedia/pax-mongolica",img:"",meta:"Encyclopedia · Idea",why:"The idea behind the relatively safe passage of goods, envoys and travellers across Mongol-ruled Eurasia."},
    {name:"Timurid Empire",href:"/empire/timurid-empire",img:"/images/encyclopedia/kamal-ud-din-behzad.jpg",meta:"Profile · 1363 CE – 1507 CE",why:"Caravan trade between China, India and the Mediterranean enriched Samarkand, Bukhara and Herat, a late flowering of the overland routes."}
  ]},
  {slug:"steppe-empires",title:"Empires of the Steppe",tagline:"How mounted nomads built some of the largest states in history, from the Xiongnu to Timur.",types:["strategist","timekeeper"],intro:"The grasslands stretching from Mongolia to the Black Sea produced a distinctive kind of empire: mobile, built on horses and herds, held together by charismatic leaders and tribute rather than bureaucracy. Steppe powers repeatedly humbled settled neighbours, extracted silk and grain from them and controlled the trade passing between them. This path traces that tradition from the Xiongnu confederation that confronted Han China, through the Turkic khaganates, to Genghis Khan's world empire and its heirs.",steps:[
    {name:"Xiongnu Empire",href:"/empire/xiongnu-empire",img:"/images/encyclopedia/luoyang.jpg",meta:"Profile · 318 BCE – 36 BCE",why:"The first great steppe empire of eastern Eurasia, united by Modu Chanyu around 209 BCE, forced Han China into decades of appeasement."},
    {name:"Heqin",href:"/encyclopedia/heqin",img:"",meta:"Encyclopedia · Institution",why:"The 'peace through kinship' arrangement of annual gifts and Han brides that bought peace from the Xiongnu after the Battle of Baideng."},
    {name:"Gokturk Empire",href:"/empire/gokturk-empire",img:"/images/encyclopedia/western-wei.jpg",meta:"Profile · 546 CE – 744 CE",why:"Founded by Bumin in 552, the first state to bear the name Türk managed Silk Road commerce and left the Orkhon Inscriptions."},
    {name:"Khazar Khaganate",href:"/empire/khazar-khaganate",img:"/images/encyclopedia/byzantine-empire.jpg",meta:"Profile · 650 CE – 969 CE",why:"A western steppe power poised between Byzantium and the caliphate, notable for its religious pluralism and its rulers' conversion to Judaism."},
    {name:"Genghis Khan",href:"/encyclopedia/genghis-khan",img:"/images/encyclopedia/genghis-khan.jpg",meta:"Encyclopedia · Person · born 1162",why:"Temüjin unified the rival Mongol and Turkic tribes and was proclaimed Genghis Khan at a kurultai in 1206."},
    {name:"Mongol Empire",href:"/empire/mongol-empire",img:"/images/encyclopedia/karakorum.jpg",meta:"Profile · 1206 CE – 1368 CE",why:"Decimal units, promotion by merit and the yam relay system carried Mongol armies from China to Legnica and Mohi by 1241."},
    {name:"Yasa",href:"/encyclopedia/yasa",img:"",meta:"Encyclopedia · Institution",why:"The body of Mongol customary law that Genghis Khan's heirs, Chagatai above all, enforced across the conquered lands."},
    {name:"Chagatai Empire",href:"/empire/chagatai-empire",img:"/images/encyclopedia/kaidu.jpg",meta:"Profile · 1225 CE – 1500 CE",why:"The Central Asian appanage of Genghis Khan's second son shows the lasting tension between nomadic tradition and the sedentary Silk Road cities."},
    {name:"Timur",href:"/encyclopedia/timur",img:"/images/encyclopedia/timur.jpg",meta:"Encyclopedia · Person",why:"Rising within the Chagatai Khanate, Timur used the Mongol framework of legitimacy to build an empire from Anatolia to the borders of China."}
  ]},
  {slug:"religion-and-power",title:"Religion and Power",tagline:"How rulers adopted, promoted and imposed faiths, and how faith in turn shaped their states.",types:["thinker"],intro:"Empires have rarely been neutral about belief. Some rulers embraced a new faith and spread it across their realms; others used religion to claim legitimacy, to unite diverse subjects or to set themselves apart from rivals. This path moves from Ashoka's dhamma, Constantine's patronage of the Church and Ezana's conversion, through the first caliphs and the crowning of Charlemagne, to the crusades, Safavid Shi'ism and Akbar's policy of peace with all, showing faith as both foundation and fault line.",steps:[
    {name:"Maurya Empire",href:"/empire/maurya-empire",img:"/images/encyclopedia/chandragupta-maurya.jpg",meta:"Profile · 322 BCE – 185 BCE",why:"After the bloody Kalinga War, Ashoka renounced conquest by force, and royal patronage helped spread Buddhism across the subcontinent and beyond."},
    {name:"Edicts of Ashoka",href:"/encyclopedia/edicts-of-ashoka",img:"/images/encyclopedia/edicts-of-ashoka.jpg",meta:"Encyclopedia · Work",why:"Inscribed on rocks and pillars, the edicts proclaimed dhamma and welfare measures, even naming Hellenistic kings as recipients of Ashoka's missions."},
    {name:"Edict of Milan",href:"/encyclopedia/edict-of-milan",img:"/images/encyclopedia/edict-of-milan.jpg",meta:"Encyclopedia · Event · 313 CE",why:"The agreement of 313 between Constantine and Licinius that set a persecuted sect on the road to becoming Rome's dominant institution."},
    {name:"Aksumite Empire",href:"/empire/aksumite-empire",img:"/images/encyclopedia/rock-hewn-churches-of-lalibela.jpg",meta:"Profile · 100 CE – 940 CE",why:"King Ezana's adoption of Christianity in the fourth century made the church a major pillar of Aksumite government."},
    {name:"Rashidun Caliphate",href:"/empire/rashidun-caliphate",img:"/images/encyclopedia/yazdegerd-iii.jpg",meta:"Profile · 632 CE – 661 CE",why:"The first caliphs, successors to the Prophet Muhammad, turned a religious community into an empire reaching Syria, Egypt and Iraq."},
    {name:"Coronation of Charlemagne",href:"/encyclopedia/coronation-of-charlemagne",img:"/images/encyclopedia/coronation-of-charlemagne.jpg",meta:"Encyclopedia · Event · 800 CE",why:"On Christmas Day 800 Pope Leo III crowned Charlemagne in Rome, sealing the alliance between the papacy and the Frankish monarchy."},
    {name:"Crusades",href:"/encyclopedia/crusades",img:"",meta:"Encyclopedia · Event",why:"Centuries of holy war in the name of faith, including the irony of 1204, when crusaders sacked Christian Constantinople."},
    {name:"Safavid Empire",href:"/empire/safavid-empire",img:"/images/encyclopedia/naqsh-e-jahan-square.jpg",meta:"Profile · 1501 CE – 1736 CE",why:"Ismail I proclaimed Twelver Shia Islam the state religion in 1501, forging an Iranian identity distinct from his Sunni Ottoman and Uzbek neighbours."},
    {name:"Mughal Empire",href:"/empire/mughal-empire",img:"/images/encyclopedia/taj-mahal.jpg",meta:"Profile · 1526 CE – 1857 CE",why:"Akbar's Sulh-i-kul, or 'peace with all', and his abolition of the jizya in 1564 contrast with Aurangzeb's return to orthodoxy."}
  ]},
  {slug:"empires-of-africa",title:"Empires of Africa",tagline:"Gold, faith and trade in the great states of Nubia, Ethiopia and West Africa.",types:["timekeeper","navigator"],intro:"Africa's empires were built on control of gold, trade routes and the loyalty of diverse peoples. Kush ruled Egypt as its Twenty-Fifth Dynasty; Aksum struck its own gold coins and traded with Rome and India; and in West Africa a succession of states, Ghana, Mali and Songhai, grew rich on the trans-Saharan exchange of gold and salt. This path follows that story from the Nile to the forest kingdom of Asante, whose Golden Stool embodied the soul of the nation.",steps:[
    {name:"Kushite Empire",href:"/empire/kushite-empire",img:"/images/encyclopedia/kashta.jpg",meta:"Profile · 1070 BCE – 350 CE",why:"From Napata, Piye and his successors united Nubia and Egypt as the Twenty-Fifth Dynasty, before Meroë became a great centre of iron."},
    {name:"Aksumite Empire",href:"/empire/aksumite-empire",img:"/images/encyclopedia/rock-hewn-churches-of-lalibela.jpg",meta:"Profile · 100 CE – 940 CE",why:"Controlling the Red Sea port of Adulis, Aksum issued its own gold coins and conquered Kush around 350 CE."},
    {name:"Ghana Empire",href:"/empire/ghana-empire",img:"/images/encyclopedia/abu-bakr-ibn-umar.jpg",meta:"Profile · 300 CE – 1240 CE",why:"The Soninke 'land of gold' taxed both salt moving south and gold moving north, reserving every gold nugget for the king."},
    {name:"Sundiata Keita",href:"/encyclopedia/sundiata-keita",img:"",meta:"Encyclopedia · Person · d. c. 1255",why:"The founder of Mali, whose victory at Kirina united the Manding chiefdoms and whose epic is still preserved by griots."},
    {name:"Mali Empire",href:"/empire/mali-empire",img:"/images/encyclopedia/djenne.jpg",meta:"Profile · 1235 CE – 1600 CE",why:"Mali controlled the goldfields of Bambuk and Bure and made Timbuktu and Djenné centres of trade and Islamic learning."},
    {name:"Mansa Musa's pilgrimage",href:"/encyclopedia/mansa-musas-pilgrimage",img:"",meta:"Encyclopedia · Event · 1324",why:"Mansa Musa's lavish spending of gold in Cairo in 1324 put Mali on the map, quite literally in the Catalan Atlas."},
    {name:"Songhai Empire",href:"/empire/songhai-empire",img:"/images/encyclopedia/gao.jpg",meta:"Profile · 1430 CE – 1600 CE",why:"The largest empire in West African history, built by Sunni Ali and Askia Muhammad on the cities of Gao, Timbuktu and Djenné."},
    {name:"Battle of Tondibi",href:"/encyclopedia/battle-of-tondibi",img:"",meta:"Encyclopedia · Event · 1591",why:"In 1591 a small Moroccan force armed with arquebuses routed a much larger Songhai army in a single engagement."},
    {name:"Ashanti Empire",href:"/empire/ashanti-empire",img:"/images/encyclopedia/golden-stool.jpg",meta:"Profile · 1670 CE – 1902 CE",why:"Osei Tutu I and the priest Okomfo Anokye united the Akan chiefdoms around the Golden Stool and defeated Denkyira at Feyiase in 1701."}
  ]},
  {slug:"age-of-sail",title:"The Age of Sail",tagline:"How small Atlantic kingdoms and a merchant republic built empires across the oceans.",types:["navigator","strategist"],intro:"From the fifteenth century, European ships opened sea routes that linked the continents as never before. Portugal led the way down the African coast and into the Indian Ocean; Spain crossed the Atlantic and seized the wealth of the Americas; the Dutch built a company with the powers of a state; and Britain eventually assembled the largest empire in history. This path follows that expansion, and the enslavement and violence on which much of it rested.",steps:[
    {name:"Portuguese Empire",href:"/empire/portuguese-empire",img:"/images/encyclopedia/john-i-of-portugal.jpg",meta:"Profile · 1415 CE – 1975 CE",why:"From the capture of Ceuta in 1415 to Goa, Malacca and Hormuz, Portugal built an empire of fortified trading posts rather than territory."},
    {name:"Prince Henry the Navigator",href:"/encyclopedia/prince-henry-the-navigator",img:"/images/encyclopedia/prince-henry-the-navigator.jpg",meta:"Encyclopedia · Person",why:"Henry's sponsorship of voyages down the West African coast turned exploration from episodic raiding into an institutionalised commercial enterprise."},
    {name:"Vasco da Gama",href:"/encyclopedia/vasco-da-gama",img:"/images/encyclopedia/vasco-da-gama.jpg",meta:"Encyclopedia · Person · 1498",why:"Da Gama's arrival at Calicut in 1498 completed the sea route to Asia that Bartolomeu Dias had opened by rounding the Cape."},
    {name:"Treaty of Tordesillas",href:"/encyclopedia/treaty-of-tordesillas",img:"/images/encyclopedia/treaty-of-tordesillas.jpg",meta:"Encyclopedia · Event · 1494",why:"The treaty of 1494 fixed a meridian dividing newly discovered lands between the Spanish and Portuguese spheres."},
    {name:"Spanish Empire",href:"/empire/spanish-empire",img:"/images/encyclopedia/francisco-de-vitoria.jpg",meta:"Profile · 1492 CE – 1898 CE",why:"Columbus, Cortés and Pizarro made Spain master of the Americas, and under Philip II the first empire on which the sun never set."},
    {name:"Atlantic slave trade",href:"/encyclopedia/atlantic-slave-trade",img:"",meta:"Encyclopedia · Term",why:"Plantation economies such as Brazil's sugar estates rested on the forced transport of enslaved Africans across the Atlantic."},
    {name:"Dutch Empire",href:"/empire/dutch-empire",img:"/images/encyclopedia/hugo-grotius.jpg",meta:"Profile · 1581 CE – 1975 CE",why:"A small republic projected power across four continents by seizing maritime chokepoints such as Malacca, taken from Portugal in 1641."},
    {name:"Dutch East India Company",href:"/encyclopedia/dutch-east-india-company",img:"/images/encyclopedia/dutch-east-india-company.jpg",meta:"Encyclopedia · Institution",why:"Founded in 1602 with permanent capital, tradable shares and powers to wage war and make treaties, the VOC was something new."},
    {name:"British Empire",href:"/empire/british-empire",img:"/images/encyclopedia/slavery-abolition-act-1833.jpg",meta:"Profile · 1583 CE – 1997 CE",why:"Built on a fiscal-military state and a professional Royal Navy, it became the largest empire in history, ruling roughly a quarter of the world's population."}
  ]},
  {slug:"how-empires-fall",title:"How Empires Fall",tagline:"Invasion, division, bankruptcy and revolution: the many ways great powers come to an end.",types:["strategist","timekeeper"],intro:"No empire lasts for ever, but they end in strikingly different ways. Some erode slowly until a final blow merely confirms what has already happened; others are destroyed in a single catastrophe. This path compares the fall of the Western Roman Empire, the Mongol destruction of Abbasid Baghdad, the Ottoman conquest of Constantinople, the collapse of Qing China and the dissolution of the Ottoman Empire itself, asking what internal weakness and external pressure each contributed.",steps:[
    {name:"Roman Empire",href:"/empire/roman-empire",img:"/images/encyclopedia/julius-caesar.jpg",meta:"Profile · 27 BCE – 476 CE",why:"Adrianople, the Visigothic sack of 410 and the loss of North Africa stripped the Western Empire of armies, prestige and revenue."},
    {name:"Sack of Rome (410)",href:"/encyclopedia/sack-of-rome-410",img:"",meta:"Encyclopedia · Event · 410 CE",why:"Alaric's Visigoths shattered the myth of Roman invulnerability, though the Western Empire limped on for another sixty-six years."},
    {name:"Abbasid Caliphate",href:"/empire/abbasid-caliphate",img:"/images/encyclopedia/al-kitab-al-mukhtasar-fi-hisab-al-jabr-wal-muqabala.jpg",meta:"Profile · 750 CE – 1517 CE",why:"Once the commercial hub of the known world, the caliphate had long ceased to be a first-rank military power when the Mongols arrived."},
    {name:"Siege of Baghdad (1258)",href:"/encyclopedia/siege-of-baghdad-1258",img:"",meta:"Encyclopedia · Event · 1258",why:"The Mongol destruction of Baghdad in 1258 ended the caliphate there, although a shadow caliphate survived under the Mamluks in Cairo."},
    {name:"Byzantine Empire",href:"/empire/byzantine-empire",img:"/images/encyclopedia/second-arab-siege-of-constantinople.jpg",meta:"Profile · 330 CE – 1453 CE",why:"A civilisation that saw its own decline clearly: the loss of Anatolia and the crusader sack of 1204 did damage it never repaired."},
    {name:"Fall of Constantinople",href:"/encyclopedia/fall-of-constantinople",img:"/images/encyclopedia/fall-of-constantinople.jpg",meta:"Encyclopedia · Event · 1453",why:"On 29 May 1453 Mehmed II's cannon breached the Theodosian walls, extinguishing the Byzantine Empire after eleven centuries."},
    {name:"Qing Empire",href:"/empire/qing-empire",img:"/images/encyclopedia/opium-wars.jpg",meta:"Profile · 1644 CE – 1912 CE",why:"Fiscal strain, rebellions such as the Taiping and defeat in the Opium Wars hollowed out China's last dynasty from within and without."},
    {name:"Xinhai Revolution",href:"/encyclopedia/xinhai-revolution",img:"/images/encyclopedia/xinhai-revolution.jpg",meta:"Encyclopedia · Event · 1911",why:"An uprising at Wuchang in 1911 spread from province to province and led to Puyi's abdication, ending two thousand years of imperial rule."},
    {name:"Ottoman Empire",href:"/empire/ottoman-empire",img:"/images/encyclopedia/suleymaniye-mosque.jpg",meta:"Profile · 1299 CE – 1922 CE",why:"The conqueror of Constantinople endured until defeat in the First World War and the abolition of the sultanate in 1922."}
  ]},
  {slug:"law-and-government",title:"Law and Government",tagline:"From Hammurabi's stele to the Napoleonic Code: how empires wrote down the rules.",types:["thinker","builder"],intro:"Conquest wins territory, but only law and administration hold it. Rulers across the world have codified laws, set out principles of statecraft and built institutions to bind diverse subjects to a single authority. This path follows some of the most influential examples: the laws of Hammurabi, the Arthashastra's manual of statecraft, Justinian's codification of Roman law, the Tang Code that shaped East Asia, Mali's founding charter and Napoleon's civil code, whose influence still reaches across continents.",steps:[
    {name:"Babylonian Empire",href:"/empire/babylonian-empire",img:"/images/encyclopedia/sin-muballit.jpg",meta:"Profile · 1894 BCE – 1595 BCE",why:"Hammurabi turned a modest kingdom into the master of Mesopotamia through patient preparation, shrewd diplomacy and rapid conquest."},
    {name:"Code of Hammurabi",href:"/encyclopedia/code-of-hammurabi",img:"/images/encyclopedia/code-of-hammurabi.jpg",meta:"Encyclopedia · Work · c. 1754 BCE",why:"Inscribed on a basalt stele now in the Louvre, its 282 laws regulated wages, loans, contracts and the duties of merchants."},
    {name:"Arthashastra",href:"/encyclopedia/arthashastra",img:"",meta:"Encyclopedia · Work",why:"Attributed to Chanakya, this guide to administration, espionage, law and diplomacy is often used to illuminate Mauryan government."},
    {name:"Byzantine Empire",href:"/empire/byzantine-empire",img:"/images/encyclopedia/second-arab-siege-of-constantinople.jpg",meta:"Profile · 330 CE – 1453 CE",why:"Byzantium joined Roman codified law and professional administration to a Christian ideology of the emperor as God's chosen representative."},
    {name:"Corpus Juris Civilis",href:"/encyclopedia/corpus-juris-civilis",img:"/images/encyclopedia/corpus-juris-civilis.jpg",meta:"Encyclopedia · Work · 534 CE",why:"Justinian's codification of 529 to 534, rediscovered and taught at Bologna, became the foundation of civil law across much of the world."},
    {name:"Tang Code",href:"/encyclopedia/tang-code",img:"",meta:"Encyclopedia · Work · 653",why:"First issued in 624, the Tang Code influenced the legal systems of Japan, Korea and Vietnam, Japan's Taihō Code among them."},
    {name:"Kouroukan Fouga",href:"/encyclopedia/kouroukan-fouga",img:"/images/encyclopedia/kouroukan-fouga.jpg",meta:"Encyclopedia · Work",why:"The assembly and charter credited to Sundiata, regulating succession, clan obligations and social order in the Mali Empire."},
    {name:"French Empire",href:"/empire/french-empire",img:"/images/encyclopedia/charles-de-gaulle.jpg",meta:"Profile · 1534 CE – 1980 CE",why:"France carried its law overseas: in Algeria French civil law applied to European settlers, while most Algerians lived under the indigénat."},
    {name:"Napoleonic Code",href:"/encyclopedia/napoleonic-code",img:"/images/encyclopedia/napoleonic-code.jpg",meta:"Encyclopedia · Work",why:"Spread across Europe in Napoleon's wake and later by colonial rule, it shaped legal systems in Africa and the Americas."}
  ]},
  {slug:"science-and-learning",title:"Science and Learning",tagline:"Libraries, translators and observatories: where empires invested in knowledge.",types:["thinker"],intro:"Imperial wealth has often paid for knowledge. Kings and caliphs founded libraries, endowed colleges, sponsored translations and built observatories, sometimes for prestige, sometimes for practical ends such as calendars and administration. This path visits the scholars of Ptolemaic Alexandria, the mathematicians of Gupta India, the translators of Abbasid Baghdad, the calendar reformers of the Seljuk court, the inventors of Song China and Ulugh Beg's astronomers in Samarkand, tracing how ideas passed from one centre of learning to the next.",steps:[
    {name:"Ptolemaic Empire",href:"/empire/ptolemaic-empire",img:"/images/encyclopedia/euclid.jpg",meta:"Profile · 323 BCE – 30 BCE",why:"Ptolemaic Alexandria drew scholars such as Euclid, Eratosthenes and Herophilus to its Library and Mouseion."},
    {name:"Library of Alexandria",href:"/encyclopedia/library-of-alexandria",img:"/images/encyclopedia/library-of-alexandria.jpg",meta:"Encyclopedia · Institution",why:"The great royal library at the heart of Ptolemaic scholarship, whose reputation has shaped the ideal of a universal library ever since."},
    {name:"Gupta Empire",href:"/empire/gupta-empire",img:"/images/encyclopedia/abhijnanasakuntalam.jpg",meta:"Profile · 240 CE – 550 CE",why:"India's Golden Age produced Kalidasa's poetry and Aryabhata's astronomy, built on the place-value decimal system later transmitted to Europe."},
    {name:"Abbasid Caliphate",href:"/empire/abbasid-caliphate",img:"/images/encyclopedia/al-kitab-al-mukhtasar-fi-hisab-al-jabr-wal-muqabala.jpg",meta:"Profile · 750 CE – 1517 CE",why:"From Baghdad, founded in 762, the Abbasids presided over a cosmopolitan court where al-Khwarizmi wrote his treatise on al-jabr."},
    {name:"House of Wisdom",href:"/encyclopedia/house-of-wisdom",img:"/images/encyclopedia/house-of-wisdom.jpg",meta:"Encyclopedia · Institution",why:"The centre that translated Greek, Persian, Indian and Syriac texts into Arabic, preserving Aristotle, Euclid, Galen and Ptolemy."},
    {name:"Omar Khayyam",href:"/encyclopedia/omar-khayyam",img:"/images/encyclopedia/omar-khayyam.jpg",meta:"Encyclopedia · Person",why:"Poet and mathematician who, under Seljuk patronage, produced the Jalali calendar of 1079, more accurate than the Julian calendar."},
    {name:"Song Dynasty",href:"/empire/song-dynasty",img:"/images/encyclopedia/bi-sheng.jpg",meta:"Profile · 960 CE – 1279 CE",why:"Song China issued state paper money from 1024, first recorded the gunpowder formula in 1044 and chose officials by written examination."},
    {name:"Timurid Empire",href:"/empire/timurid-empire",img:"/images/encyclopedia/kamal-ud-din-behzad.jpg",meta:"Profile · 1363 CE – 1507 CE",why:"Rebuilt with the plunder of Timur's conquests, Samarkand became under Shah Rukh and Ulugh Beg a genuine centre of intellectual life."},
    {name:"Ulugh Beg Observatory",href:"/encyclopedia/ulugh-beg-observatory",img:"/images/encyclopedia/ulugh-beg-observatory.jpg",meta:"Encyclopedia · Institution",why:"Built in the 1420s, its tables listed more than a thousand stars and were later published at Oxford in 1665."}
  ]},
  {slug:"the-crusades",title:"The Crusades",tagline:"Two centuries of holy war for the eastern Mediterranean, and the states it built and broke.",types:["strategist","chronicler"],intro:"In 1095 a pope's sermon set armed pilgrims marching east, and for two hundred years Latin Christendom fought for Jerusalem and the coast of the Levant. The crusades planted fragile kingdoms in the East, bled Byzantium, raised up Saladin and the sultans who answered the call to jihad, and bound Europe to the Mediterranean world it had half-forgotten. This path follows the whole arc, from Clermont to the fall of the crusader states.",steps:[
    {name:"Pope Urban II",href:"/encyclopedia/pope-urban-ii",img:"/images/encyclopedia/pope-urban-ii.jpg",meta:"Encyclopedia · Person · 1095",why:"The pope whose sermon at Clermont in 1095 launched the First Crusade."},
    {name:"First Crusade",href:"/encyclopedia/first-crusade",img:"/images/encyclopedia/first-crusade.jpg",meta:"Encyclopedia · Event · captured Jerusalem 1099",why:"Against every expectation, the first expedition took Jerusalem in 1099 and made the crusading idea seem blessed."},
    {name:"Kingdom of Jerusalem",href:"/empire/kingdom-of-jerusalem",img:"/images/encyclopedia/church-of-the-holy-sepulchre.jpg",meta:"Profile · 1099 CE – 1291 CE",why:"The greatest of the crusader states: how a conquered coast was ruled, defended and finally lost."},
    {name:"Saladin",href:"/encyclopedia/saladin",img:"/images/encyclopedia/saladin.jpg",meta:"Encyclopedia · Person · d. 1193",why:"The Kurdish sultan who united Egypt and Syria and turned the tide of the holy war."},
    {name:"Battle of Hattin",href:"/encyclopedia/battle-of-hattin",img:"/images/encyclopedia/battle-of-hattin.jpg",meta:"Encyclopedia · Event · 1187",why:"One July day in 1187 destroyed the kingdom's army and gave Jerusalem back to Islam."},
    {name:"Krak des Chevaliers",href:"/encyclopedia/krak-des-chevaliers",img:"/images/encyclopedia/krak-des-chevaliers.jpg",meta:"Encyclopedia · Work",why:"The greatest of the crusader castles, and what fortress architecture reveals about holding hostile land."},
    {name:"Fourth Crusade",href:"/encyclopedia/fourth-crusade",img:"/images/encyclopedia/fourth-crusade.jpg",meta:"Encyclopedia · Event · 1204",why:"The crusade that never reached Jerusalem: it sacked Christian Constantinople instead, and Byzantium never fully recovered."},
    {name:"Crusader states",href:"/encyclopedia/crusader-states",img:"/images/encyclopedia/crusader-states.jpg",meta:"Encyclopedia · State",why:"The settlements as a whole - Edessa, Antioch, Tripoli, Jerusalem - and why they could not last."}
  ]},
  {slug:"the-fall-of-rome",title:"The Fall of Rome",tagline:"How the western half of the ancient world's greatest state came apart.",types:["timekeeper","strategist"],intro:"Rome did not fall in a day, and half of it did not fall at all. This path traces the long unravelling of the western empire: the reforms that bought time, the frontier that broke at Adrianople, the sacks of the eternal city, and the quiet afternoon in 476 when a barbarian general sent the imperial regalia east. It ends with the Gothic kings who kept the lights on in Italy and the eastern empire that carried Rome onward for a thousand years.",steps:[
    {name:"Roman Empire",href:"/empire/roman-empire",img:"/images/encyclopedia/julius-caesar.jpg",meta:"Profile · 27 BCE – 476 CE",why:"Begin with the whole story: the power the fifth century inherited and squandered."},
    {name:"Diocletian",href:"/encyclopedia/diocletian",img:"/images/encyclopedia/diocletian.jpg",meta:"Encyclopedia · Person · r. 284–305 CE",why:"The reformer who split the empire to save it, a century before the end."},
    {name:"Battle of Adrianople",href:"/encyclopedia/battle-of-adrianople",img:"/images/encyclopedia/battle-of-adrianople.jpg",meta:"Encyclopedia · Event · 378 CE",why:"378 CE: the Goths destroyed an emperor and his army, and the frontier never truly closed again."},
    {name:"Alaric I",href:"/encyclopedia/alaric-i",img:"/images/encyclopedia/alaric-i.jpg",meta:"Encyclopedia · Person",why:"The Gothic king whose army took Rome in 410, the first sack in eight centuries."},
    {name:"Attila",href:"/encyclopedia/attila",img:"",meta:"Encyclopedia · Person · c. 406–453",why:"The Hun who bled both empires and showed how little stood behind the walls."},
    {name:"Odoacer",href:"/encyclopedia/odoacer",img:"/images/encyclopedia/odoacer.jpg",meta:"Encyclopedia · Person",why:"The soldier who deposed the last western emperor in 476 and ruled Italy as king."},
    {name:"Theodoric the Great",href:"/encyclopedia/theodoric-the-great",img:"/images/encyclopedia/theodoric-the-great.jpg",meta:"Encyclopedia · Person · 454–526",why:"The Ostrogoth who governed Italy in Roman style: the fall, seen from the inside, looked like continuity."},
    {name:"Byzantine Empire",href:"/empire/byzantine-empire",img:"/images/encyclopedia/second-arab-siege-of-constantinople.jpg",meta:"Profile · 330 CE – 1453 CE",why:"The half that did not fall: Rome's eastern empire endured to 1453."}
  ]},
  {slug:"the-americas-before-columbus",title:"The Americas before Columbus",tagline:"Great cities, empires and roads built long before 1492.",types:["navigator","builder"],intro:"When Europeans arrived, the Americas already held some of the largest cities on earth, roads that outran anything in Europe, and empires that had risen and fallen for two thousand years. This path crosses that world: the metropolis of Teotihuacan, the island capital of the Aztecs, and the Inca realm that ran ten thousand kilometres of mountain road - and the two emperors who met the conquistadors.",steps:[
    {name:"Teotihuacan",href:"/empire/teotihuacan",img:"/images/encyclopedia/templo-mayor.jpg",meta:"Profile · 100 BCE – 550 CE",why:"A city of a hundred thousand people, planned on a grid, that shaped Mesoamerica centuries before the Aztecs."},
    {name:"Aztec Empire",href:"/empire/aztec-empire",img:"/images/encyclopedia/florentine-codex.jpg",meta:"Profile · 1325 CE – 1521 CE",why:"The last and greatest power of Mesoamerica: tribute, war and a capital on a lake."},
    {name:"Tenochtitlan",href:"/encyclopedia/tenochtitlan",img:"/images/encyclopedia/tenochtitlan.jpg",meta:"Encyclopedia · Place",why:"The island metropolis that stunned the Spaniards, larger than most cities of Europe."},
    {name:"Moctezuma II",href:"/encyclopedia/moctezuma-ii",img:"/images/encyclopedia/moctezuma-ii.jpg",meta:"Encyclopedia · Person",why:"The emperor who received Cortes, and whose fate still divides historians."},
    {name:"Inca Empire",href:"/empire/inca-empire",img:"/images/encyclopedia/machu-picchu.jpg",meta:"Profile · 1438 CE – 1533 CE",why:"The largest state of the pre-Columbian Americas, run by roads, storehouses and knotted cords instead of writing."},
    {name:"Machu Picchu",href:"/encyclopedia/machu-picchu",img:"/images/encyclopedia/machu-picchu.jpg",meta:"Encyclopedia · Place",why:"The royal estate in the clouds that conquest never found."},
    {name:"Atahualpa",href:"/encyclopedia/atahualpa",img:"/images/encyclopedia/atahualpa.jpg",meta:"Encyclopedia · Person · c. 1502–1533",why:"The Inca who won a civil war just in time to meet Pizarro at Cajamarca."}
  ]},
  {slug:"india-through-the-ages",title:"India through the Ages",tagline:"From Ashoka's edicts to the Marathas: the subcontinent's great powers in sequence.",types:["timekeeper","chronicler"],intro:"Few lands have carried so many great states as the Indian subcontinent. This path moves through them in order: the Mauryan empire that first united the subcontinent and the emperor who renounced war; the classical age of the Guptas; the sultans of Delhi; the glittering south of Vijayanagara; the Mughal zenith and its monuments; and the Maratha confederacy that supplanted it.",steps:[
    {name:"Maurya Empire",href:"/empire/maurya-empire",img:"/images/encyclopedia/chandragupta-maurya.jpg",meta:"Profile · 322 BCE – 185 BCE",why:"The first empire to span the subcontinent, with a bureaucracy ahead of its time."},
    {name:"Ashoka",href:"/encyclopedia/ashoka",img:"/images/encyclopedia/ashoka.jpg",meta:"Encyclopedia · Person · d. 232 BCE",why:"The conqueror of Kalinga who turned to dhamma and carved his conscience onto rocks and pillars."},
    {name:"Gupta Empire",href:"/empire/gupta-empire",img:"/images/encyclopedia/abhijnanasakuntalam.jpg",meta:"Profile · 240 CE – 550 CE",why:"The classical age: mathematics, poetry and temple art under a light imperial hand."},
    {name:"Delhi Sultanate",href:"/empire/delhi-sultanate",img:"/images/encyclopedia/qutb-minar.jpg",meta:"Profile · 1206 CE – 1526 CE",why:"Three centuries of sultans who made Delhi one of the great capitals of the Islamic world."},
    {name:"Vijayanagara Empire",href:"/empire/vijayanagara-empire",img:"/images/encyclopedia/vedas.jpg",meta:"Profile · 1336 CE – 1646 CE",why:"The city of victory that ruled the south and awed every traveller who saw it."},
    {name:"Mughal Empire",href:"/empire/mughal-empire",img:"/images/encyclopedia/taj-mahal.jpg",meta:"Profile · 1526 CE – 1857 CE",why:"From Babur to Aurangzeb: the richest empire on earth in its day."},
    {name:"Akbar",href:"/encyclopedia/akbar",img:"/images/encyclopedia/akbar.jpg",meta:"Encyclopedia · Person · r. 1556–1605",why:"The Mughal who ruled by inclusion, debating every faith at his court."},
    {name:"Taj Mahal",href:"/encyclopedia/taj-mahal",img:"/images/encyclopedia/taj-mahal.jpg",meta:"Encyclopedia · Work",why:"Grief in white marble: the empire's wealth and craft in one building."},
    {name:"Maratha Empire",href:"/empire/maratha-empire",img:"/images/encyclopedia/shivaji.jpg",meta:"Profile · 1674 CE – 1818 CE",why:"The confederacy that broke Mughal power and dominated eighteenth-century India."}
  ]},
  {slug:"china-dynasty-by-dynasty",title:"China, Dynasty by Dynasty",tagline:"Two thousand years of the world's most durable state tradition.",types:["timekeeper","builder"],intro:"No polity on earth has been reinvented as many times as China. This path takes the dynastic story in sequence - Han foundations, Tang cosmopolitanism and its great rebellion, Song brilliance, the Mongol century, Ming voyages and walls, and the Qing empire at its vast height - asking each time what survived the fall and carried over.",steps:[
    {name:"Han Dynasty",href:"/empire/han-dynasty",img:"/images/encyclopedia/liu-bang.jpg",meta:"Profile · 206 BCE – 220 CE",why:"The dynasty that defined China: the examination ideal, the historian's craft and the Silk Road."},
    {name:"Tang Dynasty",href:"/empire/tang-dynasty",img:"/images/encyclopedia/emperor-gaozu-of-tang.jpg",meta:"Profile · 618 CE – 907 CE",why:"Chang'an at its height was the largest, most cosmopolitan city on earth."},
    {name:"An Lushan Rebellion",href:"/encyclopedia/an-lushan-rebellion",img:"/images/encyclopedia/an-lushan-rebellion.jpg",meta:"Encyclopedia · Event · 755–763",why:"The catastrophe of 755 that broke the Tang world and echoed for a century."},
    {name:"Song Dynasty",href:"/empire/song-dynasty",img:"/images/encyclopedia/bi-sheng.jpg",meta:"Profile · 960 CE – 1279 CE",why:"Paper money, printing, gunpowder and the richest economy of the medieval world."},
    {name:"Yuan Dynasty",href:"/empire/yuan-dynasty",img:"/images/encyclopedia/kublai-khan.jpg",meta:"Profile · 1271 CE – 1368 CE",why:"The Mongol century: China inside the largest land empire in history."},
    {name:"Ming Empire",href:"/empire/ming-empire",img:"/images/encyclopedia/manila.jpg",meta:"Profile · 1368 CE – 1644 CE",why:"Restoration, the Forbidden City, and the choice to turn inward."},
    {name:"Zheng He",href:"/encyclopedia/zheng-he",img:"/images/encyclopedia/zheng-he.jpg",meta:"Encyclopedia · Person",why:"The admiral whose treasure fleets reached Africa decades before the Portuguese."},
    {name:"Qing Empire",href:"/empire/qing-empire",img:"/images/encyclopedia/opium-wars.jpg",meta:"Profile · 1644 CE – 1912 CE",why:"The last dynasty doubled China's size, then met the nineteenth century."}
  ]},
  {slug:"the-age-of-revolutions",title:"The Age of Revolutions",tagline:"Half a century in which subjects became citizens on three continents.",types:["chronicler","thinker"],intro:"Between 1775 and 1830 the political world turned upside down. Thirteen colonies defied an empire; France beheaded its king and exported revolution by arms; the enslaved of Saint-Domingue freed themselves and founded a state; and South America's liberators unmade the oldest colonial empire of all. This path follows the chain reaction.",steps:[
    {name:"American Revolution",href:"/encyclopedia/american-revolution",img:"/images/encyclopedia/american-revolution.jpg",meta:"Encyclopedia · Event · 1765–1783",why:"The war and the ideas that turned thirteen colonies into a republic."},
    {name:"French Revolution",href:"/encyclopedia/french-revolution",img:"/images/encyclopedia/french-revolution.jpg",meta:"Encyclopedia · Event · 1789–1799",why:"The revolution that devoured a monarchy and redefined politics everywhere."},
    {name:"Storming of the Bastille",href:"/encyclopedia/storming-of-the-bastille",img:"/images/encyclopedia/storming-of-the-bastille.jpg",meta:"Encyclopedia · Event · 1789",why:"14 July 1789: the day the crowd entered history."},
    {name:"French Empire",href:"/empire/french-empire",img:"/images/encyclopedia/charles-de-gaulle.jpg",meta:"Profile · 1534 CE – 1980 CE",why:"Napoleon carried the revolution's code, and its armies, across Europe."},
    {name:"Haitian Revolution",href:"/encyclopedia/haitian-revolution",img:"/images/encyclopedia/haitian-revolution.jpg",meta:"Encyclopedia · Event · 1791–1804",why:"The only successful revolution of the enslaved, and the age's most radical act."},
    {name:"Simón Bolívar",href:"/encyclopedia/simon-bolivar",img:"/images/encyclopedia/simon-bolivar.jpg",meta:"Encyclopedia · Person · 1783–1830",why:"The Liberator of six nations, and the disappointments of victory."},
    {name:"Gran Colombia",href:"/empire/gran-colombia",img:"/images/encyclopedia/quito.jpg",meta:"Profile · 1819 CE – 1831 CE",why:"Bolivar's great experiment: a united South American republic, and why it broke apart."}
  ]},
  {slug:"women-who-ruled",title:"Women Who Ruled",tagline:"Nine rulers who held power in their own right, from the Nile to the Forbidden City.",types:["chronicler"],intro:"In most ages the rules said a woman could not rule, and in every age some did anyway. This path crosses four millennia of them: a pharaoh who wore the false beard, warrior queens who fought Rome, the only woman to found a Chinese dynasty, an African queen who out-negotiated an empire, and the empresses who steered Russia and China through their most dangerous centuries.",steps:[
    {name:"Hatshepsut",href:"/encyclopedia/hatshepsut",img:"/images/encyclopedia/hatshepsut.jpg",meta:"Encyclopedia · Person · c. 1479–1458 BCE",why:"The pharaoh who ruled Egypt for two decades and built like a king."},
    {name:"Cleopatra VII",href:"/encyclopedia/cleopatra-vii",img:"/images/encyclopedia/cleopatra-vii.jpg",meta:"Encyclopedia · Person · r. 51–30 BCE",why:"The last Ptolemy, who played Rome's strongmen against each other for twenty years."},
    {name:"Boudica",href:"/encyclopedia/boudica",img:"/images/encyclopedia/boudica.jpg",meta:"Encyclopedia · Person · d. 60 or 61",why:"The Iceni queen whose revolt burned Roman London."},
    {name:"Zenobia",href:"/encyclopedia/zenobia",img:"/images/encyclopedia/zenobia.jpg",meta:"Encyclopedia · Person · c. 240–after 274",why:"The queen of Palmyra who carved an empire from Rome's east."},
    {name:"Wu Zetian",href:"/encyclopedia/wu-zetian",img:"/images/encyclopedia/wu-zetian.jpg",meta:"Encyclopedia · Person · r. 690–705",why:"The only woman to rule China as emperor in her own name."},
    {name:"Seondeok of Silla",href:"/encyclopedia/seondeok-of-silla",img:"",meta:"Encyclopedia · Person · d. 647",why:"Korea's first reigning queen, patron of scholars and stargazers."},
    {name:"Njinga of Ndongo and Matamba",href:"/encyclopedia/njinga-of-ndongo-and-matamba",img:"/images/encyclopedia/njinga-of-ndongo-and-matamba.jpg",meta:"Encyclopedia · Person · c. 1583–1663",why:"The queen who fought and out-bargained the Portuguese for forty years."},
    {name:"Elizabeth I",href:"/encyclopedia/elizabeth-i",img:"/images/encyclopedia/elizabeth-i.jpg",meta:"Encyclopedia · Person · 1533–1603",why:"Gloriana: the unmarried queen who made a weak realm a power."},
    {name:"Catherine the Great",href:"/encyclopedia/catherine-the-great",img:"/images/encyclopedia/catherine-the-great.jpg",meta:"Encyclopedia · Person",why:"The empress who seized a throne and an age and gave Russia both."}
  ]},
  {slug:"city-states-and-leagues",title:"City-States and Leagues",tagline:"How single cities and their alliances outfought and outtraded empires.",types:["builder","navigator"],intro:"Not every great power was an empire. Some were single cities with harbours, fleets and ruthless bookkeeping. This path visits the city-states that punched far above their size - Athens and Carthage in the ancient Mediterranean, Venice and Novgorod at the two ends of medieval Europe's trade, and the Hanseatic league of cities that ran the northern seas without a king at all.",steps:[
    {name:"Athens",href:"/empire/athens",img:"/images/encyclopedia/parthenon.jpg",meta:"Profile · 900 BCE – 86 BCE",why:"The democracy that built an Aegean empire on triremes and tribute."},
    {name:"Punic Empire",href:"/empire/punic-empire",img:"/images/encyclopedia/iarbas.jpg",meta:"Profile · 814 BCE – 146 BCE",why:"Carthage: a merchant city that fought three wars with Rome for the western Mediterranean."},
    {name:"Republic of Venice",href:"/empire/republic-of-venice",img:"/images/encyclopedia/paolo-lucio-anafesto.jpg",meta:"Profile · 697 CE – 1797 CE",why:"The lagoon republic that turned shipping lanes into an empire of islands and counting houses."},
    {name:"Fourth Crusade",href:"/encyclopedia/fourth-crusade",img:"/images/encyclopedia/fourth-crusade.jpg",meta:"Encyclopedia · Event · 1204",why:"Venice at its most ruthless: a crusade redirected to its commercial rivals' capital."},
    {name:"Novgorod Republic",href:"/empire/novgorod-republic",img:"/images/encyclopedia/church-of-the-transfiguration-on-ilyina-street.jpg",meta:"Profile · 1136 CE – 1478 CE",why:"The merchant republic of the Russian north, where the assembly could dismiss a prince."},
    {name:"Hanseatic League",href:"/empire/hanseatic-league",img:"/images/encyclopedia/bryggen.jpg",meta:"Profile · 1356 CE – 1669 CE",why:"A league of trading cities that made treaties, fought wars and set prices from London to Novgorod."}
  ]},
  {slug:"great-conquerors",title:"The Great Conquerors",tagline:"Eight lives that redrew the map, from Cyrus to Napoleon.",types:["strategist","chronicler"],intro:"A handful of commanders have bent whole continents to their will, and history has argued about them ever since. This path follows eight of them in order, asking what each conquest cost, what it built, and what outlived the conqueror.",steps:[
    {name:"Cyrus the Great",href:"/encyclopedia/cyrus-the-great",img:"/images/encyclopedia/cyrus-the-great.jpg",meta:"Encyclopedia · Person · acceded 559 BCE",why:"The founder of the Persian empire, remembered as much for tolerance as for conquest."},
    {name:"Alexander the Great",href:"/encyclopedia/alexander-the-great",img:"/images/encyclopedia/alexander-the-great.jpg",meta:"Encyclopedia · Person · r. 336–323 BCE",why:"Master of the ancient world by thirty-two, dead a year later; the empire broke, the Greek century it opened did not."},
    {name:"Julius Caesar",href:"/encyclopedia/julius-caesar",img:"/images/encyclopedia/julius-caesar.jpg",meta:"Encyclopedia · Person",why:"Gaul conquered, the Republic broken: the general whose name became a title on three continents."},
    {name:"Attila",href:"/encyclopedia/attila",img:"",meta:"Encyclopedia · Person · c. 406–453",why:"The Hun who bled two Roman empires and vanished with his realm within a decade."},
    {name:"Genghis Khan",href:"/encyclopedia/genghis-khan",img:"/images/encyclopedia/genghis-khan.jpg",meta:"Encyclopedia · Person · born 1162",why:"From orphan of the steppe to ruler of the largest land empire in history."},
    {name:"Timur",href:"/encyclopedia/timur",img:"/images/encyclopedia/timur.jpg",meta:"Encyclopedia · Person",why:"The last great steppe conqueror, builder of Samarkand and destroyer of nearly everyone else."},
    {name:"Suleiman the Magnificent",href:"/encyclopedia/suleiman-the-magnificent",img:"/images/encyclopedia/suleiman-the-magnificent.jpg",meta:"Encyclopedia · Person",why:"Lawgiver to the Ottomans and terror of Europe, at the summit of a dynasty's power."},
    {name:"Napoleon",href:"/encyclopedia/napoleon",img:"/images/encyclopedia/napoleon.jpg",meta:"Encyclopedia · Person",why:"The artillery officer who crowned himself emperor and forced all Europe to reorganise against him."}
  ]},
  {slug:"explorers-and-travellers",title:"Explorers and Travellers",tagline:"Seven journeys that stitched the world together.",types:["navigator","chronicler"],intro:"Before the world was mapped it was walked, ridden and sailed, often by people who had little idea what lay ahead. This path follows seven travellers whose journeys, and whose accounts of them, changed what the world knew about itself.",steps:[
    {name:"Xuanzang",href:"/encyclopedia/xuanzang",img:"/images/encyclopedia/xuanzang.jpg",meta:"Encyclopedia · Person · 602–664",why:"The Tang monk who walked to India for scriptures and came back a legend."},
    {name:"Marco Polo",href:"/encyclopedia/marco-polo",img:"/images/encyclopedia/marco-polo.jpg",meta:"Encyclopedia · Person · 1275–1292 in China",why:"A Venetian in the service of Kublai Khan, whose book gave Europe its picture of Asia."},
    {name:"Ibn Battuta",href:"/encyclopedia/ibn-battuta",img:"/images/encyclopedia/ibn-battuta.jpg",meta:"Encyclopedia · Person · 1334–1341 at Delhi",why:"Thirty years and some 120,000 kilometres across the Islamic world and beyond."},
    {name:"Zheng He",href:"/encyclopedia/zheng-he",img:"/images/encyclopedia/zheng-he.jpg",meta:"Encyclopedia · Person",why:"Treasure fleets to Arabia and Africa, decades before Europe rounded the Cape."},
    {name:"Christopher Columbus",href:"/encyclopedia/christopher-columbus",img:"/images/encyclopedia/christopher-columbus.jpg",meta:"Encyclopedia · Person",why:"Four voyages that joined two worlds and began a catastrophe and an age at once."},
    {name:"Vasco da Gama",href:"/encyclopedia/vasco-da-gama",img:"/images/encyclopedia/vasco-da-gama.jpg",meta:"Encyclopedia · Person · 1498",why:"The sea road to India, and the gun-backed trade empire that followed it."},
    {name:"Ferdinand Magellan",href:"/encyclopedia/ferdinand-magellan",img:"/images/encyclopedia/ferdinand-magellan.jpg",meta:"Encyclopedia · Person · c. 1480–1521",why:"The expedition that proved the world round by sailing it, though its commander never came home."}
  ]},
  {slug:"the-great-historians",title:"The Great Historians",tagline:"The writers who invented how we remember the past.",types:["thinker","chronicler"],intro:"History is itself a human invention, with inventors. This path reads five of them: the Greek who first called his inquiry historia, the exile who dissected power, the Roman hostage who explained Rome to the conquered, China's grand historian, and the North African judge who asked why states rise and fall at all.",steps:[
    {name:"Herodotus",href:"/encyclopedia/herodotus",img:"/images/encyclopedia/herodotus.jpg",meta:"Encyclopedia · Person",why:"The father of history: travel, marvels and the Persian Wars, told so the deeds of men not fade."},
    {name:"Thucydides",href:"/encyclopedia/thucydides",img:"/images/encyclopedia/thucydides.jpg",meta:"Encyclopedia · Person · c. 460–c. 400 BCE",why:"The Peloponnesian War by a general who fought in it, history as unflinching analysis of power."},
    {name:"Polybius",href:"/encyclopedia/polybius",img:"/images/encyclopedia/polybius.jpg",meta:"Encyclopedia · Person · c. 200–c. 118 BCE",why:"A Greek hostage in Rome who set out to explain, in forty books, how one city conquered his world in fifty-three years."},
    {name:"Sima Qian",href:"/encyclopedia/sima-qian",img:"/images/encyclopedia/sima-qian.jpg",meta:"Encyclopedia · Person · c. 145–c. 86 BCE",why:"China's grand historian, who chose disgrace over silence to finish the Records that shaped two millennia of Chinese memory."},
    {name:"Ibn Khaldun",href:"/encyclopedia/ibn-khaldun",img:"/images/encyclopedia/ibn-khaldun.jpg",meta:"Encyclopedia · Person · 1332–1406",why:"The Muqaddimah's author, who made the rise and fall of dynasties a science centuries before sociology had a name."}
  ]},
  {slug:"founders-of-world-religions",title:"Founders of World Religions",tagline:"Eight teachers whose words outlived every empire of their day.",types:["thinker","chronicler"],intro:"The longest-lived institutions in history are not states but faiths. This path visits eight founders and reformers in rough chronological order, treating each historically: what we know of their lives, what they taught, and how communities carried those teachings across continents and millennia.",steps:[
    {name:"Zoroaster",href:"/encyclopedia/zoroaster",img:"",meta:"Encyclopedia · Person · c. 1200–1000 BCE (disputed)",why:"The prophet of ancient Iran whose vision of truth against the lie is among the oldest revealed religions."},
    {name:"Gautama Buddha",href:"/encyclopedia/gautama-buddha",img:"/images/encyclopedia/gautama-buddha.jpg",meta:"Encyclopedia · Person",why:"The prince who left a palace to understand suffering, and whose middle way crossed all Asia."},
    {name:"Confucius",href:"/encyclopedia/confucius",img:"/images/encyclopedia/confucius.jpg",meta:"Encyclopedia · Person · 551–479 BCE",why:"A failed official whose teaching on duty and ritual became the operating system of East Asian states."},
    {name:"Laozi",href:"/encyclopedia/laozi",img:"",meta:"Encyclopedia · Person · 6th–4th century BCE (traditional)",why:"The elusive sage of the Daodejing and the way that cannot be spoken."},
    {name:"Jesus",href:"/encyclopedia/jesus",img:"/images/encyclopedia/jesus.jpg",meta:"Encyclopedia · Person · c. 4 BCE – c. 30/33 CE",why:"A teacher in Roman Judaea whose following became the faith of empires."},
    {name:"Muhammad",href:"/encyclopedia/muhammad",img:"",meta:"Encyclopedia · Person · c. 570–632",why:"The prophet of Islam, whose community became a civilisation within a century of his death."},
    {name:"Guru Nanak",href:"/encyclopedia/guru-nanak",img:"",meta:"Encyclopedia · Person · 1469–1539",why:"The founder of Sikhism, teaching one God and the equality of all people."},
    {name:"Martin Luther",href:"/encyclopedia/martin-luther",img:"/images/encyclopedia/martin-luther.jpg",meta:"Encyclopedia · Person · 1483–1546",why:"The monk whose ninety-five theses split Western Christendom and remade Europe's map."}
  ]},
  {slug:"rebels-against-empire",title:"Rebels against Empire",tagline:"Six risings against the greatest powers of their age.",types:["chronicler","strategist"],intro:"Every empire in this collection was defied by someone who refused its terms. This path follows six of them, enslaved and royal, doomed and triumphant, and asks what their revolts changed, whether they won or lost.",steps:[
    {name:"Spartacus",href:"/encyclopedia/spartacus",img:"/images/encyclopedia/spartacus.jpg",meta:"Encyclopedia · Person · d. 71 BCE",why:"The gladiator whose army of the enslaved shook Rome for two years."},
    {name:"Vercingetorix",href:"/encyclopedia/vercingetorix",img:"/images/encyclopedia/vercingetorix.jpg",meta:"Encyclopedia · Person · c. 82–46 BCE",why:"The chief who united Gaul against Caesar, and paid for it in a Roman triumph."},
    {name:"Arminius",href:"/encyclopedia/arminius",img:"/images/encyclopedia/arminius.jpg",meta:"Encyclopedia · Person",why:"The Roman-trained officer who annihilated three legions and fixed the empire's frontier at the Rhine."},
    {name:"Boudica",href:"/encyclopedia/boudica",img:"/images/encyclopedia/boudica.jpg",meta:"Encyclopedia · Person · d. 60 or 61",why:"The queen whose revolt burned three Roman towns before it broke."},
    {name:"Túpac Amaru II",href:"/encyclopedia/tupac-amaru-ii",img:"/images/encyclopedia/tupac-amaru-ii.jpg",meta:"Encyclopedia · Person · 1738–1781",why:"The Andean rising of 1780 that shook Spanish Peru to its foundations."},
    {name:"Toussaint Louverture",href:"/encyclopedia/toussaint-louverture",img:"/images/encyclopedia/toussaint-louverture.jpg",meta:"Encyclopedia · Person",why:"The general of the enslaved who defeated three empires and made Haiti possible."}
  ]},
  {slug:"the-great-builders",title:"The Great Builders",tagline:"Rulers who built their worlds in stone, law and cities.",types:["builder","chronicler"],intro:"Some rulers are remembered for what they destroyed; these are remembered for what they raised. This path crosses four millennia of builders, of codes and canals, libraries and basilicas, mosques, palaces and whole capitals, and asks what building meant to power.",steps:[
    {name:"Hammurabi",href:"/encyclopedia/hammurabi",img:"/images/encyclopedia/hammurabi.jpg",meta:"Encyclopedia · Person · r. c. 1792–1750 BCE",why:"The Babylonian king whose law code, carved in stone, is among the oldest surviving statements of justice."},
    {name:"Ashurbanipal",href:"/encyclopedia/ashurbanipal",img:"/images/encyclopedia/ashurbanipal.jpg",meta:"Encyclopedia · Person · r. 669–627 BCE",why:"Assyria's last great king, whose library at Nineveh preserved Mesopotamia's literature for us to find."},
    {name:"Justinian I",href:"/encyclopedia/justinian-i",img:"/images/encyclopedia/justinian-i.jpg",meta:"Encyclopedia · Person",why:"The emperor of Hagia Sophia and the Corpus Juris, Rome's law given its final form."},
    {name:"Charlemagne",href:"/encyclopedia/charlemagne",img:"/images/encyclopedia/charlemagne.jpg",meta:"Encyclopedia · Person",why:"The Frankish king whose schools and scripts carried learning through Europe's leanest centuries."},
    {name:"Mansa Musa",href:"/encyclopedia/mansa-musa",img:"/images/encyclopedia/mansa-musa.jpg",meta:"Encyclopedia · Person · r. 1312–1337",why:"Mali's pilgrim emperor, whose gold built Timbuktu's mosques and reputation."},
    {name:"Shah Jahan",href:"/encyclopedia/shah-jahan",img:"/images/encyclopedia/shah-jahan.jpg",meta:"Encyclopedia · Person · 1592–1666",why:"The Mughal of the Taj Mahal, grief made architecture."},
    {name:"Louis XIV",href:"/encyclopedia/louis-xiv",img:"/images/encyclopedia/louis-xiv.jpg",meta:"Encyclopedia · Person",why:"Versailles as a machine of rule: the builder-king who domesticated an aristocracy."},
    {name:"Peter the Great",href:"/encyclopedia/peter-the-great",img:"/images/encyclopedia/peter-the-great.jpg",meta:"Encyclopedia · Person",why:"The tsar who built a capital on a swamp to force Russia's face towards Europe."}
  ]},
  {slug:"capitals-of-the-world",title:"Capitals of the World",tagline:"Eight cities where power lived.",types:["builder","navigator"],intro:"Every age has a city where the world's business seems to be decided. This path walks through eight of them at their height, from the gates of Babylon to the lakes of Tenochtitlan, asking what made each the centre of its world and what remains.",steps:[
    {name:"Babylon",href:"/encyclopedia/babylon",img:"/images/encyclopedia/babylon.jpg",meta:"Encyclopedia · Place",why:"Gate of the gods: the ancient world's byword for the great city."},
    {name:"Rome",href:"/encyclopedia/rome",img:"/images/encyclopedia/rome.jpg",meta:"Encyclopedia · Place",why:"A million people at the centre of the Mediterranean world."},
    {name:"Constantinople",href:"/encyclopedia/constantinople",img:"/images/encyclopedia/constantinople.jpg",meta:"Encyclopedia · Place",why:"The new Rome on the Bosphorus, besieged by everyone and taken almost never."},
    {name:"Baghdad",href:"/encyclopedia/baghdad",img:"/images/encyclopedia/baghdad.jpg",meta:"Encyclopedia · Place",why:"The round city of the caliphs, where the world's learning was translated."},
    {name:"Chang'an",href:"/encyclopedia/changan",img:"/images/encyclopedia/changan.jpg",meta:"Encyclopedia · Place",why:"The Tang capital, the largest city on earth and the eastern end of the Silk Road."},
    {name:"Córdoba",href:"/encyclopedia/cordoba",img:"",meta:"Encyclopedia · Place",why:"Umayyad Córdoba, where al-Andalus outshone every city of Latin Europe."},
    {name:"Cusco",href:"/encyclopedia/cusco",img:"/images/encyclopedia/cusco.jpg",meta:"Encyclopedia · Place",why:"The navel of the Inca world, from which the four quarters ran."},
    {name:"Tenochtitlan",href:"/encyclopedia/tenochtitlan",img:"/images/encyclopedia/tenochtitlan.jpg",meta:"Encyclopedia · Place",why:"The island capital on the lake, larger than the European cities of its conquerors."}
  ]},
  {slug:"turning-point-battles",title:"Turning-Point Battles",tagline:"Eight days of fighting on which centuries turned.",types:["strategist"],intro:"Most battles decide little; a few decide eras. This path examines eight engagements whose outcomes redirected history, not for the drama alone, but for what each reveals about the states that fought and the worlds that followed.",steps:[
    {name:"Battle of Marathon",href:"/encyclopedia/battle-of-marathon",img:"/images/encyclopedia/battle-of-marathon.jpg",meta:"Encyclopedia · Event · 490 BCE",why:"The Greek line held, and with it the independence that made the classical world possible."},
    {name:"Battle of Gaugamela",href:"/encyclopedia/battle-of-gaugamela",img:"/images/encyclopedia/battle-of-gaugamela.jpg",meta:"Encyclopedia · Event · 331 BCE",why:"One afternoon ended two centuries of Persian empire and opened Asia to Alexander."},
    {name:"Battle of Actium",href:"/encyclopedia/battle-of-actium",img:"/images/encyclopedia/battle-of-actium.jpg",meta:"Encyclopedia · Event · 31 BCE",why:"The sea battle that ended Rome's civil wars and began its emperors."},
    {name:"Battle of Tours",href:"/encyclopedia/battle-of-tours",img:"/images/encyclopedia/battle-of-tours.jpg",meta:"Encyclopedia · Event · 732 CE",why:"The Frankish victory that fixed the limit of the Arab advance into western Europe."},
    {name:"Battle of Manzikert",href:"/encyclopedia/battle-of-manzikert",img:"",meta:"Encyclopedia · Event · 1071",why:"The day Anatolia began to turn Turkish, and Byzantium began its long retreat."},
    {name:"Battle of Ain Jalut",href:"/encyclopedia/battle-of-ain-jalut",img:"/images/encyclopedia/battle-of-ain-jalut.jpg",meta:"Encyclopedia · Event · 1260",why:"The Mamluks stopped the Mongols, the first time the conquerors of everywhere were turned back for good."},
    {name:"Battle of Lepanto",href:"/encyclopedia/battle-of-lepanto",img:"/images/encyclopedia/battle-of-lepanto.jpg",meta:"Encyclopedia · Event · 1571",why:"The last great battle of oared ships broke the spell of Ottoman invincibility at sea."},
    {name:"Battle of Waterloo",href:"/encyclopedia/battle-of-waterloo",img:"/images/encyclopedia/battle-of-waterloo.jpg",meta:"Encyclopedia · Event",why:"The afternoon that closed a quarter-century of world war and set Europe's order for a century."}
  ]},
  {slug:"wonders-and-monuments",title:"Wonders and Monuments",tagline:"What the great builders left standing.",types:["builder","navigator"],intro:"Stone keeps promises that documents cannot. This path visits eight monuments, from the one surviving ancient wonder to a Mughal tomb, reading each as evidence: of the state that raised it, the labour that built it, and the beliefs it was meant to outlast.",steps:[
    {name:"Great Pyramid of Giza",href:"/encyclopedia/great-pyramid-of-giza",img:"/images/encyclopedia/great-pyramid-of-giza.jpg",meta:"Encyclopedia · Work · c. 2560 BCE",why:"The oldest of the seven wonders and the only one still standing."},
    {name:"Great Wall of China",href:"/encyclopedia/great-wall-of-china",img:"/images/encyclopedia/great-wall-of-china.jpg",meta:"Encyclopedia · Work",why:"Two thousand years of walls against the steppe, joined into one idea."},
    {name:"Petra",href:"/encyclopedia/petra",img:"/images/encyclopedia/petra.jpg",meta:"Encyclopedia · Place",why:"A caravan city carved into rose-red rock at the crossroads of incense routes."},
    {name:"Hagia Sophia",href:"/encyclopedia/hagia-sophia",img:"/images/encyclopedia/hagia-sophia.jpg",meta:"Encyclopedia · Work · 537 CE",why:"Justinian's dome, church then mosque then museum then mosque, fifteen centuries at the centre of two faiths."},
    {name:"Angkor Wat",href:"/encyclopedia/angkor-wat",img:"/images/encyclopedia/angkor-wat.jpg",meta:"Encyclopedia · Work",why:"The largest religious monument on earth, the Khmer state in stone."},
    {name:"Alhambra",href:"/encyclopedia/alhambra",img:"/images/encyclopedia/alhambra.jpg",meta:"Encyclopedia · Work",why:"The last palace of al-Andalus, beauty built on a falling frontier."},
    {name:"Machu Picchu",href:"/encyclopedia/machu-picchu",img:"/images/encyclopedia/machu-picchu.jpg",meta:"Encyclopedia · Place",why:"An Inca royal estate the conquest never found."},
    {name:"Taj Mahal",href:"/encyclopedia/taj-mahal",img:"/images/encyclopedia/taj-mahal.jpg",meta:"Encyclopedia · Work",why:"The Mughal empire's wealth and craft condensed into one tomb."}
  ]},
  {slug:"plagues-and-pandemics",title:"Plagues and Pandemics",tagline:"How disease has redirected history as surely as any army.",types:["timekeeper","thinker"],intro:"Microbes have ended more dynasties than generals have. This path follows disease through history, from the plague that broke Justinian's reconquest to the smallpox that emptied continents, asking how societies broke, adapted and rebuilt.",steps:[
    {name:"Black Death",href:"/encyclopedia/black-death",img:"/images/encyclopedia/black-death.jpg",meta:"Encyclopedia · Event",why:"A third to half of Europe dead in seven years, and the medieval order with them."},
    {name:"Smallpox",href:"/encyclopedia/smallpox",img:"",meta:"Encyclopedia · Term",why:"The conqueror that travelled with the conquistadors and did most of their work."},
    {name:"Byzantine Empire",href:"/empire/byzantine-empire",img:"/images/encyclopedia/second-arab-siege-of-constantinople.jpg",meta:"Profile · 330 CE – 1453 CE",why:"Justinian's plague arrived at the empire's height and helped bury his reconquest of the West."},
    {name:"Aztec Empire",href:"/empire/aztec-empire",img:"/images/encyclopedia/florentine-codex.jpg",meta:"Profile · 1325 CE – 1521 CE",why:"An empire of millions brought down as much by epidemics as by Spanish steel."},
    {name:"First World War",href:"/encyclopedia/first-world-war",img:"/images/encyclopedia/first-world-war.jpg",meta:"Encyclopedia · Event",why:"The war whose ending coincided with the deadliest influenza in history."}
  ]},
  {slug:"the-world-wars",title:"The World Wars",tagline:"Three decades that ended the age of empires.",types:["strategist","timekeeper"],intro:"Between 1914 and 1945 the states of Europe fought two wars that consumed the world and, in the end, their own empires. This path follows the arc from Sarajevo to Hiroshima: the war that broke four empires, the peace that failed, and the war that finished what the first began.",steps:[
    {name:"First World War",href:"/encyclopedia/first-world-war",img:"/images/encyclopedia/first-world-war.jpg",meta:"Encyclopedia · Event",why:"Four years that killed four empires: Hohenzollern, Habsburg, Romanov and Ottoman."},
    {name:"Treaty of Versailles",href:"/encyclopedia/treaty-of-versailles",img:"/images/encyclopedia/treaty-of-versailles.jpg",meta:"Encyclopedia · Event",why:"The peace that ended the war and seeded the next."},
    {name:"German Empire",href:"/empire/german-empire",img:"/images/encyclopedia/war-guilt-clause.jpg",meta:"Profile · 1871 CE – 1918 CE",why:"The rising power whose fears and ambitions drove the July crisis of 1914."},
    {name:"Empire of Japan",href:"/empire/empire-of-japan",img:"/images/encyclopedia/emperor-meiji.jpg",meta:"Profile · 1868 CE – 1945 CE",why:"The one non-European empire of the age, from Meiji ascent to 1945."},
    {name:"Second World War",href:"/encyclopedia/second-world-war",img:"/images/encyclopedia/second-world-war.jpg",meta:"Encyclopedia · Event",why:"The deadliest war in history, and the end of Europe's centuries at the centre of the world."},
    {name:"Atomic bombings of Hiroshima and Nagasaki",href:"/encyclopedia/atomic-bombings-of-hiroshima-and-nagasaki",img:"/images/encyclopedia/atomic-bombings-of-hiroshima-and-nagasaki.jpg",meta:"Encyclopedia · Event · 1945",why:"The weeks that ended the war and opened an age in which great-power war risks everything."},
    {name:"British Empire",href:"/empire/british-empire",img:"/images/encyclopedia/slavery-abolition-act-1833.jpg",meta:"Profile · 1583 CE – 1997 CE",why:"Victorious and exhausted: how winning two world wars still cost an empire."}
  ]},
  {slug:"money-and-trade",title:"Money and Trade",tagline:"The routes, coins and companies that moved the world.",types:["builder","navigator"],intro:"Armies take headlines, but trade pays for them. This path follows wealth through history, silk and spice, caravans and sea lanes, the banks that financed empires and the company that became one, asking how commerce built and broke the powers of every age.",steps:[
    {name:"Silk",href:"/encyclopedia/silk",img:"",meta:"Encyclopedia · Term",why:"The fibre that named a road and moved ideas along with cloth."},
    {name:"Trans-Saharan trade",href:"/encyclopedia/trans-saharan-trade",img:"",meta:"Encyclopedia · Term",why:"Gold north, salt south: the caravans that made Ghana, Mali and Songhai."},
    {name:"Indian Ocean trade",href:"/encyclopedia/indian-ocean-trade",img:"",meta:"Encyclopedia · Term",why:"The monsoon exchange that linked Africa, Arabia, India and China long before Europeans arrived."},
    {name:"Spice trade",href:"/encyclopedia/spice-trade",img:"",meta:"Encyclopedia · Term",why:"Cloves and pepper: small cargoes worth fortunes, and the wars fought to corner them."},
    {name:"Republic of Venice",href:"/empire/republic-of-venice",img:"/images/encyclopedia/paolo-lucio-anafesto.jpg",meta:"Profile · 697 CE – 1797 CE",why:"The middleman city that grew rich on the eastern trade and fought to keep it."},
    {name:"Dutch East India Company",href:"/encyclopedia/dutch-east-india-company",img:"/images/encyclopedia/dutch-east-india-company.jpg",meta:"Encyclopedia · Institution",why:"The joint-stock company with a flag, an army and an empire of its own."},
    {name:"Bank of Amsterdam",href:"/encyclopedia/bank-of-amsterdam",img:"/images/encyclopedia/bank-of-amsterdam.jpg",meta:"Encyclopedia · Institution · 1609–1820",why:"The bank at the heart of the first modern financial centre."}
  ]}
];
